main.script:
function switchMainImage(element) {
    var newSrc = element.getAttribute('data-src');
    var mainImg = document.getElementById('product_main_image');
    if (mainImg) {
        mainImg.src = newSrc;
    }
    var thumbs = document.querySelectorAll('.thumbnail-item');
    thumbs.forEach(function(t) {
        t.classList.remove('border-primary', 'border-2', 'border-secondary');
        t.classList.add('border-outline-variant', 'border');
    });
    element.classList.remove('border-outline-variant', 'border');
    element.classList.add('border-secondary', 'border-2');
}

function submitAndGoToCart(event) {
    event.preventDefault();
    var form = event.target.closest('form');
    if (form) {
        var formData = new FormData(form);
        fetch(form.action, {
            method: 'POST',
            body: formData
        }).then(function() {
            window.location.href = '/shop/cart';
        }).catch(function() {
            window.location.href = '/shop/cart';
        });
    }
}

function filterReviews(filterType, element) {
    // Active/Inactive styles
    var buttons = element.parentNode.querySelectorAll('button');
    buttons.forEach(function(btn) {
        btn.classList.remove('border-secondary', 'text-secondary', 'font-semibold');
        btn.classList.add('border-gray-200', 'text-[#222]');
    });
    element.classList.remove('border-gray-200', 'text-[#222]');
    element.classList.add('border-secondary', 'text-secondary', 'font-semibold');

    // Filter list items
    var reviews = document.querySelectorAll('.review-item');
    reviews.forEach(function(rev) {
        var stars = Math.round(parseFloat(rev.getAttribute('data-stars') || '0'));
        var hasComment = rev.getAttribute('data-has-comment') === 'true';

        if (filterType === 'all') {
            rev.style.display = 'flex';
        } else if (filterType === '5') {
            rev.style.display = (stars === 5) ? 'flex' : 'none';
        } else if (filterType === '4') {
            rev.style.display = (stars === 4) ? 'flex' : 'none';
        } else if (filterType === '3') {
            rev.style.display = (stars === 3) ? 'flex' : 'none';
        } else if (filterType === '2') {
            rev.style.display = (stars === 2) ? 'flex' : 'none';
        } else if (filterType === '1') {
            rev.style.display = (stars === 1) ? 'flex' : 'none';
        } else if (filterType === 'comment') {
            rev.style.display = hasComment ? 'flex' : 'none';
        }
    });
}

function showCartToast(data) {
    var existing = document.getElementById('cart-toast');
    if (existing) existing.remove();

    var toast = document.createElement('div');
    toast.id = 'cart-toast';
    toast.className = 'fixed top-24 right-4 z-[99999] w-full max-w-[400px] bg-white rounded shadow-lg border border-gray-200 overflow-hidden animate-cart-toast';
    toast.style.fontFamily = 'Inter, sans-serif';

    toast.innerHTML = 
        '<div class="flex items-start justify-between px-4 py-3 border-b border-gray-200">' +
            '<h3 class="text-[#4b5563] font-semibold text-[15px] leading-snug pr-4">Mặt hàng đã được thêm vào giỏ hàng của bạn</h3>' +
            '<button onclick="document.getElementById(\'cart-toast\').remove()" class="text-gray-400 hover:text-gray-600 transition-colors mt-0.5 shrink-0">' +
                '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">' +
                  '<path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12" />' +
                '</svg>' +
            '</button>' +
        '</div>' +
        '<div class="p-4">' +
            '<div class="flex items-start gap-4 mb-5">' +
                '<div class="w-16 h-16 bg-[#f9fafb] rounded border border-gray-100 flex items-center justify-center shrink-0">' +
                    '<img src="' + data.image_url + '" class="w-full h-full object-contain mix-blend-multiply" alt="Product Image"/>' +
                '</div>' +
                '<div class="flex-1 min-w-0 pt-0.5">' +
                    '<div class="flex justify-between items-start gap-3">' +
                        '<p class="text-[#374151] text-[15px] leading-snug">' +
                            data.added_qty + ' x ' + data.product_name +
                        '</p>' +
                        '<p class="text-[#111827] text-[15px] whitespace-nowrap">' +
                            data.product_price_formatted +
                        '</p>' +
                    '</div>' +
                '</div>' +
            '</div>' +
            '<a href="/shop/cart" class="block w-full py-2.5 bg-[#a04100] hover:bg-[#853600] text-white text-[15px] font-medium text-center rounded transition-colors shadow-sm" style="text-decoration: none;">' +
                'Xem giỏ hàng' +
            '</a>' +
        '</div>';

    document.body.appendChild(toast);

    setTimeout(function() {
        if (toast.parentNode) {
            toast.remove();
        }
    }, 8000);
}

function submitAddToCart(event) {
    event.preventDefault();
    var form = event.target;
    var formData = new FormData(form);

    var submitBtn = form.querySelector('button[type="submit"]');
    var originalHtml = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<span class="material-symbols-outlined animate-spin text-[20px]">sync</span> Thêm...';

    fetch('/shop/cart/add_json', {
        method: 'POST',
        body: formData
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalHtml;
        if (data.success) {
            var badge = document.getElementById('cart-badge');
            if (badge) {
                badge.innerText = data.total_qty;
                badge.classList.remove('hidden');
            }
            var qtyText = document.getElementById('available-qty-text');
            if (qtyText) {
                if (data.remaining_qty > 0) {
                    qtyText.innerText = data.remaining_qty;
                    qtyText.className = "";
                    qtyText.nextSibling.textContent = " sản phẩm có sẵn";
                } else {
                    qtyText.innerText = "Hết hàng";
                    qtyText.className = "text-red-500 font-medium";
                    qtyText.nextSibling.textContent = "";
                }
            }
            showCartToast(data);
        } else {
            alert('Lỗi: ' + (data.error || 'Không thể thêm vào giỏ hàng'));
        }
    })
    .catch(function(err) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalHtml;
        console.error(err);
        form.submit();
    });
}
